import java.util.Scanner;

public class Main {
    static final int MAX_CAP = 1000001; // 1e6 + 1e5
    static final int MOD_CONST = 1000000007; // 1e9 + 7

    static long base_num, mod_num;
    static int total_count;
    static long final_ans;
    static int[] visited_array = new int[MAX_CAP];
    static int[] val_array = new int[MAX_CAP];

    static void modify_value(long[] x) {
        x[0] = ((x[0] % MOD_CONST) + MOD_CONST) % MOD_CONST;
    }

    static void perform_bfs(int x) {
        total_count++;
        int start_point = x;
        long weight = 1;
        do {
            visited_array[x] = 1;
            x = (int)((x * base_num) % mod_num);
            weight = (weight * base_num) % mod_num;
        } while (x != start_point);
        long[] ansWrapper = {final_ans};
        if (weight == 1) {
            ansWrapper[0] = (ansWrapper[0] * mod_num) % MOD_CONST;
        }
        modify_value(ansWrapper);
        final_ans = ansWrapper[0];
    }

    static void main_solve() {
